// ExportRequest converts rp into an OTLP ExportProfilesServiceRequest with a
// deduplicated, orphan-free ProfilesDictionary. It returns nil if rp contains
// no profiles.
func ExportRequest(rp *profiledata.ResourceProfiles) *colprofilepb.ExportProfilesServiceRequest {
	if rp == nil || len(rp.ScopeProfiles) == 0 {
		return nil
	}

	d := newDictBuilder()
	scopeProfiles := make([]*profilepb.ScopeProfiles, 0, len(rp.ScopeProfiles))
	for i := range rp.ScopeProfiles {
		sp := &rp.ScopeProfiles[i]
		if len(sp.Profiles) == 0 {
			continue
		}
		pbProfiles := make([]*profilepb.Profile, 0, len(sp.Profiles))
		for j := range sp.Profiles {
			pbProfiles = append(pbProfiles, d.profile(&sp.Profiles[j]))
		}
		pbSP := &profilepb.ScopeProfiles{
			Profiles: pbProfiles,
		}
		var emptyScope instrumentation.Scope
		if sp.Scope != emptyScope {
			pbSP.Scope = &cpb.InstrumentationScope{
				Name:       sp.Scope.Name,
				Version:    sp.Scope.Version,
				Attributes: d.keyValuesIter(sp.Scope.Attributes.Iter()),
			}
			pbSP.SchemaUrl = sp.Scope.SchemaURL
		}
		scopeProfiles = append(scopeProfiles, pbSP)
	}

	if len(scopeProfiles) == 0 {
		return nil
	}

	pbRP := &profilepb.ResourceProfiles{
		ScopeProfiles: scopeProfiles,
	}
	if rp.Resource != nil {
		if rp.Resource.Len() > 0 {
			pbRP.Resource = &rpb.Resource{
				Attributes: d.keyValuesIter(rp.Resource.Iter()),
			}
		}
		pbRP.SchemaUrl = rp.Resource.SchemaURL()
	}

	return &colprofilepb.ExportProfilesServiceRequest{
		ResourceProfiles: []*profilepb.ResourceProfiles{pbRP},
		Dictionary:       d.dict,
	}
}

