// internAttributes interns attrs into attribute_table and returns deduplicated
// indices (last-value-wins per key to satisfy OTLP attribute_indices key
// uniqueness).
func (d *dictBuilder) internAttributes(attrs []profiledata.Attribute) []int32 {
	if len(attrs) == 0 {
		return nil
	}

	// Deduplicate by key before interning so overwritten entries do not leave
	// unreferenced strings or attributes in the dictionary.
	keyPos := make(map[attribute.Key]int, len(attrs))
	deduped := make([]profiledata.Attribute, 0, len(attrs))
	for _, a := range attrs {
		if a.Key == "" {
			continue
		}
		if pos, exists := keyPos[a.Key]; exists {
			deduped[pos] = a
		} else {
			keyPos[a.Key] = len(deduped)
			deduped = append(deduped, a)
		}
	}
	if len(deduped) == 0 {
		return nil
	}

	indices := make([]int32, len(deduped))
	for i, a := range deduped {
		indices[i] = d.internAttribute(a)
	}
	return indices
}

func (d *dictBuilder) internAttribute(a profiledata.Attribute) int32 {
	keyIdx := d.internString(string(a.Key))
	unitIdx := d.internString(a.Unit)
	pbVal, valKey := d.anyValue(a.Value)
	ak := attrKey{
		keyIdx:  keyIdx,
		unitIdx: unitIdx,
		valType: a.Value.Type(),
		valKey:  valKey,
	}
	if idx, ok := d.attrIdx[ak]; ok {
		return idx
	}
	idx := int32(len(d.dict.AttributeTable)) //nolint:gosec // Bounded by payload size.
	d.dict.AttributeTable = append(d.dict.AttributeTable, &profilepb.KeyValueAndUnit{
		KeyStrindex:  keyIdx,
		Value:        pbVal,
		UnitStrindex: unitIdx,
	})
	d.attrIdx[ak] = idx
	return idx
}

func (d *dictBuilder) keyValuesIter(iter attribute.Iterator) []*cpb.KeyValue {
	l := iter.Len()
	if l == 0 {
		return nil
	}
	out := make([]*cpb.KeyValue, 0, l)
	for iter.Next() {
		kv := iter.Attribute()
		val, _ := d.anyValue(kv.Value)
		out = append(out, &cpb.KeyValue{
			KeyStrindex: d.internString(string(kv.Key)),
			Value:       val,
		})
	}
	return out
}

func (d *dictBuilder) anyValue(v attribute.Value) (*cpb.AnyValue, string) {
	av := new(cpb.AnyValue)
	switch v.Type() {
	case attribute.BOOL:
		b := v.AsBool()
		av.Value = &cpb.AnyValue_BoolValue{BoolValue: b}
		if b {
			return av, "1"
		}
		return av, "0"
	case attribute.INT64:
		n := v.AsInt64()
		av.Value = &cpb.AnyValue_IntValue{IntValue: n}
		return av, strconv.FormatInt(n, 10)
	case attribute.FLOAT64:
		f := v.AsFloat64()
		av.Value = &cpb.AnyValue_DoubleValue{DoubleValue: f}
		return av, strconv.FormatUint(math.Float64bits(f), 16)
	case attribute.STRING:
		idx := d.internString(v.AsString())
		av.Value = &cpb.AnyValue_StringValueStrindex{StringValueStrindex: idx}
		return av, strconv.FormatInt(int64(idx), 10)
	case attribute.BYTESLICE:
		bs := v.AsByteSlice()
		av.Value = &cpb.AnyValue_BytesValue{BytesValue: slices.Clone(bs)}
		return av, hex.EncodeToString(bs)
	case attribute.BOOLSLICE:
		vals := v.AsBoolSlice()
		pbVals := make([]*cpb.AnyValue, len(vals))
		buf := make([]byte, len(vals))
		for i, b := range vals {
			pbVals[i] = &cpb.AnyValue{Value: &cpb.AnyValue_BoolValue{BoolValue: b}}
			if b {
				buf[i] = '1'
			} else {
				buf[i] = '0'
			}
		}
		av.Value = &cpb.AnyValue_ArrayValue{ArrayValue: &cpb.ArrayValue{Values: pbVals}}
		return av, string(buf)
	case attribute.INT64SLICE:
		vals := v.AsInt64Slice()
		pbVals := make([]*cpb.AnyValue, len(vals))
		var buf []byte
		for i, n := range vals {
			pbVals[i] = &cpb.AnyValue{Value: &cpb.AnyValue_IntValue{IntValue: n}}
			buf = strconv.AppendInt(buf, n, 10)
			buf = append(buf, ',')
		}
		av.Value = &cpb.AnyValue_ArrayValue{ArrayValue: &cpb.ArrayValue{Values: pbVals}}
		return av, string(buf)
	case attribute.FLOAT64SLICE:
		vals := v.AsFloat64Slice()
		pbVals := make([]*cpb.AnyValue, len(vals))
		var buf []byte
		for i, f := range vals {
			pbVals[i] = &cpb.AnyValue{Value: &cpb.AnyValue_DoubleValue{DoubleValue: f}}
			buf = strconv.AppendUint(buf, math.Float64bits(f), 16)
			buf = append(buf, ',')
		}
		av.Value = &cpb.AnyValue_ArrayValue{ArrayValue: &cpb.ArrayValue{Values: pbVals}}
		return av, string(buf)
	case attribute.STRINGSLICE:
		vals := v.AsStringSlice()
		pbVals := make([]*cpb.AnyValue, len(vals))
		var buf []byte
		for i, s := range vals {
			idx := d.internString(s)
			pbVals[i] = &cpb.AnyValue{Value: &cpb.AnyValue_StringValueStrindex{StringValueStrindex: idx}}
			buf = strconv.AppendInt(buf, int64(idx), 10)
			buf = append(buf, ',')
		}
		av.Value = &cpb.AnyValue_ArrayValue{ArrayValue: &cpb.ArrayValue{Values: pbVals}}
		return av, string(buf)
	case attribute.SLICE:
		vals := v.AsSlice()
		pbVals := make([]*cpb.AnyValue, len(vals))
		var buf []byte
		for i, elem := range vals {
			pbElem, k := d.anyValue(elem)
			pbVals[i] = pbElem
			buf = strconv.AppendInt(buf, int64(elem.Type()), 10)
			buf = append(buf, ':')
			buf = append(buf, k...)
			buf = append(buf, '\x00')
		}
		av.Value = &cpb.AnyValue_ArrayValue{ArrayValue: &cpb.ArrayValue{Values: pbVals}}
		return av, string(buf)
	case attribute.MAP:
		kvs := v.AsMap()
		pbKVs := make([]*cpb.KeyValue, len(kvs))
		var buf []byte
		for i, kv := range kvs {
			kIdx := d.internString(string(kv.Key))
			pbElem, vk := d.anyValue(kv.Value)
			pbKVs[i] = &cpb.KeyValue{KeyStrindex: kIdx, Value: pbElem}
			buf = strconv.AppendInt(buf, int64(kIdx), 10)
			buf = append(buf, '=')
			buf = strconv.AppendInt(buf, int64(kv.Value.Type()), 10)
			buf = append(buf, ':')
			buf = append(buf, vk...)
			buf = append(buf, '\x00')
		}
		av.Value = &cpb.AnyValue_KvlistValue{KvlistValue: &cpb.KeyValueList{Values: pbKVs}}
		return av, string(buf)
	case attribute.EMPTY:
		return av, ""
	default:
		idx := d.internString("INVALID")
		av.Value = &cpb.AnyValue_StringValueStrindex{StringValueStrindex: idx}
		return av, "INVALID"
	}
}

func (d *dictBuilder) encodeInt32s(vals []int32) string {
	b := d.scratch[:0]
	for _, v := range vals {
		b = strconv.AppendInt(b, int64(v), 10)
		b = append(b, ';')
	}
	d.scratch = b
	return string(b)
}

func (d *dictBuilder) encodeSortedInt32s(vals []int32) string {
	if len(vals) == 0 {
		return ""
	}
	sorted := slices.Clone(vals)
	slices.Sort(sorted)
	return d.encodeInt32s(sorted)
}

func (d *dictBuilder) encodeLines(lines []*profilepb.Line) string {
	if len(lines) == 0 {
		return ""
	}
	b := d.scratch[:0]
	for _, ln := range lines {
		b = strconv.AppendInt(b, int64(ln.FunctionIndex), 10)
		b = append(b, ':')
		b = strconv.AppendInt(b, ln.Line, 10)
		b = append(b, ':')
		b = strconv.AppendInt(b, ln.Column, 10)
		b = append(b, ';')
	}
	d.scratch = b
	return string(b)
}

func timeUnixNano(t time.Time) uint64 {
	nano := t.UnixNano()
	if nano < 0 {
		return 0
	}
	return uint64(nano) //nolint:gosec // Non-negative checked above.
}
